    @Test func zeroPrefixedFractionsParse() {
        let s = MediaTab.assetDragString(forAssetId: "x", segment: 0.0...0.5)
        #expect(MediaTab.assetSegment(fromDragString: s) == 0.0...0.5)
    }
}

import Foundation
import Testing
