@Suite("ModelDownloader — checksum")
struct ModelDownloaderTests {
    @Test func verifyAcceptsMatchAndRejectsMismatch() throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: dir) }

        let file = dir.appendingPathComponent("blob.zip")
        let data = Data("the artifact bytes".utf8)
        try data.write(to: file)
        let realHash = SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()

        try ModelDownloader.verify(file, sha256: realHash)  // correct hash → no throw

        #expect(throws: ModelDownloader.DownloadError.self) {
            try ModelDownloader.verify(file, sha256: String(repeating: "0", count: 64))
        }
    }
}

import Foundation
import Testing
@testable import PalmierPro

@MainActor
@Suite("short id round-trip")
struct ShortIdTests {
    private func uuid(_ first8: String) -> String {
        // A valid uppercase UUID whose first 8 chars are caller-controlled (for collision tests).
        "\(first8)-0000-0000-0000-000000000000"
    }

    @Test func emitsShortPrefixForFullUuid() async throws {
        let id = uuid("ABCD1234")
        let track = Fixtures.videoTrack(clips: [Fixtures.clip(id: id, start: 0, duration: 100)])
        let h = ToolHarness(timeline: Fixtures.timeline(tracks: [track]))

        let text = ToolHarness.textOf(await h.runRaw("get_timeline"))
        #expect(text.contains("ABCD1234"))
        #expect(!text.contains(id), "full uuid should not appear in output")
    }

    @Test func acceptsPrefixBackAsArgument() async throws {
        let id = uuid("ABCD1234")
        let track = Fixtures.videoTrack(clips: [Fixtures.clip(id: id, start: 0, duration: 100)])
        let h = ToolHarness(timeline: Fixtures.timeline(tracks: [track]))

        // The agent sends back the 8-char prefix it was given.
        let result = await h.runRaw("ripple_delete_ranges", args: ["clipId": "ABCD1234", "ranges": [[40, 50]]])
        #expect(result.isError == false)
        #expect(h.editor.timeline.tracks[0].clips.count == 2)
    }

    @Test func fullUuidStillResolves() async throws {
        let id = uuid("ABCD1234")
        let track = Fixtures.videoTrack(clips: [Fixtures.clip(id: id, start: 0, duration: 100)])
        let h = ToolHarness(timeline: Fixtures.timeline(tracks: [track]))

        let result = await h.runRaw("ripple_delete_ranges", args: ["clipId": id, "ranges": [[40, 50]]])
        #expect(result.isError == false)
    }

    @Test func ambiguousPrefixIsRejected() async throws {
        // Two ids share the first 8 chars, so the shared prefix can't pick one — resolve must refuse.
        let a = uuid("ABCD1234")
        let b = "ABCD1234-FFFF-0000-0000-000000000000"
        let track = Fixtures.videoTrack(clips: [
            Fixtures.clip(id: a, start: 0, duration: 100),
            Fixtures.clip(id: b, start: 200, duration: 100),
        ])
        let h = ToolHarness(timeline: Fixtures.timeline(tracks: [track]))

        let result = await h.runRaw("ripple_delete_ranges", args: ["clipId": "ABCD1234", "ranges": [[40, 50]]])
        #expect(result.isError == true)
        #expect(ToolHarness.textOf(result).localizedCaseInsensitiveContains("ambiguous"))
    }

    @Test func prefixExtendsPastSharedRun() {
        let a = uuid("ABCD1234")
        let b = "ABCD1234-FFFF-0000-0000-000000000000"
        let map = ToolExecutor.shortIdMap([a, b])
        // They share 8 chars, so each prefix must extend past the shared run to stay distinct.
        #expect(map[a] != map[b])
        #expect(map[a]!.count > 8)
    }

    @Test func unsharedIdGetsFloorLength() {
        let id = uuid("ABCD1234")
        #expect(ToolExecutor.shortIdMap([id, uuid("EEEE9999")])[id] == "ABCD1234")
    }
}

import Foundation
import Testing
@testable import PalmierPro

@Suite("FrameSampler")
struct FrameSamplerTests {
    @Test func detectsScenesAndHonorsCoverageFloor() async throws {
        let url = try await FixtureVideo.write(scenes: [
            .init(rgb: (220, 30, 30), seconds: 10),
            .init(rgb: (30, 200, 30), seconds: 10),
            .init(rgb: (30, 30, 220), seconds: 10),
        ])
        defer { try? FileManager.default.removeItem(at: url) }

        var frames: [FrameSampler.Frame] = []
        for try await frame in FrameSampler.frames(url: url, duration: 30) {
            frames.append(frame)
        }

        let shotStarts = frames.filter(\.isNewShot).map(\.time)
        #expect(shotStarts.count == 3, "expected 3 scenes, got starts at \(shotStarts)")
        #expect(frames.first?.isNewShot == true)

        // Scene boundaries land within one candidate interval of 10s and 20s.
        #expect(shotStarts.dropFirst().allSatisfy { t in
            abs(t - 10) <= 2.5 || abs(t - 20) <= 2.5
        })

        // Coverage floor: a 10s static shot keeps at least one non-boundary frame.
        #expect(frames.count > shotStarts.count)
        // Monotonic, no duplicates.
        #expect(zip(frames, frames.dropFirst()).allSatisfy { $0.time < $1.time })
    }

    @Test func shortClipGetsOneMidpointSample() async throws {
        let url = try await FixtureVideo.write(scenes: [.init(rgb: (220, 30, 30), seconds: 0.6)])
        defer { try? FileManager.default.removeItem(at: url) }

        var frames: [FrameSampler.Frame] = []
        for try await frame in FrameSampler.frames(url: url, duration: 0.6) {
            frames.append(frame)
        }
        #expect(frames.count == 1)
        #expect(frames.first?.isNewShot == true)
    }
}

import Foundation
import Testing
@testable import PalmierPro

@Suite("VisualSearch")
struct VisualSearchTests {
    static func index(vectors: [[Float]], shots: [(Double, Double, Double)]) -> EmbeddingStore.AssetIndex {
        EmbeddingStore.AssetIndex(
            header: .init(model: "test", modelVersion: 1, samplerVersion: 1, dim: vectors[0].count, count: vectors.count),
            rows: shots.map { .init(time: $0.0, shotStart: $0.1, shotEnd: $0.2) },
            vectors: vectors.flatMap { $0 }
        )
    }

    @Test func ranksAndCutsOff() {
        let idx = Self.index(
            vectors: [[1, 0, 0], [0.9, 0.1, 0], [0, 1, 0], [0, 0, 1]],
            shots: [(1, 0, 4), (5, 4, 8), (9, 8, 12), (13, 12, 16)]
        )
        let hits = VisualSearch.search(query: [1, 0, 0], indexes: [("a", idx)])
        #expect(hits.first?.time == 1)
        #expect(hits.first?.score == 1)
        // Orthogonal vectors fall below the relative cutoff.
        #expect(!hits.contains { $0.time == 9 || $0.time == 13 })
    }

    @Test func bestPerShotDedupes() {
        let idx = Self.index(
            vectors: [[1, 0, 0], [0.99, 0.01, 0], [0.5, 0.5, 0]],
            shots: [(1, 0, 10), (5, 0, 10), (9, 0, 10)]
        )
        let hits = VisualSearch.search(query: [1, 0, 0], indexes: [("a", idx)])
        #expect(hits.count == 1)
        #expect(hits.first?.time == 1)
    }

    @Test func mergesAcrossAssets() {
        let a = Self.index(vectors: [[1, 0, 0]], shots: [(1, 0, 2)])
        let b = Self.index(vectors: [[0.95, 0.05, 0]], shots: [(3, 2, 4)])
        let hits = VisualSearch.search(query: [1, 0, 0], indexes: [("a", a), ("b", b)])
        #expect(hits.map(\.assetID) == ["a", "b"])
    }

    @Test func emptyAndMismatchedDims() {
        let idx = Self.index(vectors: [[1, 0]], shots: [(1, 0, 2)])
        #expect(VisualSearch.search(query: [1, 0, 0], indexes: [("a", idx)]).isEmpty)
        #expect(VisualSearch.search(query: [1, 0], indexes: []).isEmpty)
    }

    @Test func cosineFloorDropsWeakTopMatch() {
        // A weak best-of-a-bad-batch (cos 0.04) is dropped entirely — the false-positive fix.
        let weak = Self.index(vectors: [[0.04, 0, 0]], shots: [(1, 0, 2)])
        #expect(VisualSearch.search(query: [1, 0, 0], indexes: [("a", weak)], minScore: 0.05).isEmpty)
        // Without a floor the relative cutoff still surfaces it.
        #expect(VisualSearch.search(query: [1, 0, 0], indexes: [("a", weak)]).count == 1)
        // A real match clears the floor.
        let strong = Self.index(vectors: [[0.5, 0, 0]], shots: [(1, 0, 2)])
        #expect(VisualSearch.search(query: [1, 0, 0], indexes: [("a", strong)], minScore: 0.05).count == 1)
    }
}

